1	// AreaTab.tsx — Multi-List Task Intake & ESP32 Configuration Cockpit with O(1) Inheritance
2	// Author: Faust (Serving The Manager)
3	import React, { useState, useEffect, useMemo } from 'react';
4	import {
5	  Database,
6	  CheckCircle2,
7	  RefreshCw,
8	  Link as LinkIcon,
9	  ShieldAlert,
10	  Zap,
11	  Radio,
12	  Sparkles,
13	  Check,
14	  LogIn,
15	  Key,
16	  Layers,
17	  Filter,
18	  CloudDownload,
19	  Clock,
20	  Sun,
21	  Moon,
22	  Leaf,
23	  Cpu
24	} from 'lucide-react';
25	
26	interface ListConditions {
27	  domain?: string;
28	  element?: 'solar' | 'void' | 'verdant' | 'celestial' | 'aether' | string;
29	  tags?: string[];
30	  priority_default?: string;
31	  mode_default?: string;
32	  target_seconds?: number;
33	}
34	
35	interface GoogleTaskList {
36	  id: string;
37	  title: string;
38	  conditions?: ListConditions;
39	  sort_order?: number;
40	  updated?: string;
41	}
42	
43	interface GoogleTask {
44	  id: string;
45	  tasklist_id?: string;
46	  tasklist_title?: string;
47	  conditions?: ListConditions;
48	  title: string;
49	  notes?: string;
50	  status: string;
51	  due?: string | null;
52	  updated?: string;
53	  completed?: string | null;
54	}
55	
56	interface NotionTask {
57	  id: string;
58	  title: string;
59	  status: string;
60	  priority: string;
61	  tags?: string[];
62	  dueAt?: string | null;
63	  url?: string;
64	}
65	
66	interface ESP32QueuePayload {
67	  task_id: string;
68	  title: string;
69	  tasklist_title?: string;
70	  domain?: string;
71	  element?: string;
72	  priority?: string;
73	  mode?: string;
74	  target_seconds?: number;
75	  source?: string;
76	  queue_count?: number;
77	  last_synced_at?: string | null;
78	}
79	
80	export const AreaTab: React.FC = () => {
81	  const [intakeSource, setIntakeSource] = useState<'google' | 'notion'>('google');
82	
83	  // Google Tasks State
84	  const [tasklists, setTasklists] = useState<GoogleTaskList[]>([]);
85	  const [selectedListId, setSelectedListId] = useState<string>('all');
86	  const [googleTasks, setGoogleTasks] = useState<GoogleTask[]>([]);
87	  const [isGoogleLoading, setIsGoogleLoading] = useState(false);
88	  const [isSyncingAPI, setIsSyncingAPI] = useState(false);
89	  const [isAuthorizing, setIsAuthorizing] = useState(false);
90	  const [googleStatus, setGoogleStatus] = useState<{ credentials_present: boolean; authenticated: boolean; last_synced_at?: string } | null>(null);
91	  const [lastSyncedAt, setLastSyncedAt] = useState<string | null>(null);
92	  const [completingTaskId, setCompletingTaskId] = useState<string | null>(null);
93	  const [googleError, setGoogleError] = useState<string | null>(null);
94	  const [searchQuery, setSearchQuery] = useState<string>('');
95	
96	  // Notion State
97	  const [notionDBUrl, setNotionDBUrl] = useState('3deda88f74e5802c92acc972569ff270');
98	  const [notionTasks, setNotionTasks] = useState<NotionTask[]>([]);
99	  const [isNotionLoading, setIsNotionLoading] = useState(false);
100	  const [notionError, setNotionError] = useState<string | null>(null);
101	  const [notionLastReadAt, setNotionLastReadAt] = useState<string | null>(null);
102	
103	  // ESP32 Queue State
104	  const [esp32Queue, setEsp32Queue] = useState<ESP32QueuePayload | null>(null);
105	
106	  // Initial Data Fetch
107	  useEffect(() => {
108	    fetchGoogleTasksStatus();
109	    fetchESP32Queue();
110	  }, []);
111	
112	  const fetchGoogleTasksStatus = async () => {
113	    try {
114	      const res = await fetch('http://localhost:8080/api/v1/golden-hour/google-tasks/status');
115	      const data = await res.json();
116	      setGoogleStatus(data);
117	      if (data.last_synced_at) {
118	        setLastSyncedAt(data.last_synced_at);
119	      }
120	      if (data.authenticated) {
121	        fetchTasklists();
122	        fetchGoogleTasks('all');
123	      }
124	    } catch (e) {
125	      console.warn('Backend offline:', e);
126	    }
127	  };
128	
129	  const fetchTasklists = async () => {
130	    try {
131	      const res = await fetch('http://localhost:8080/api/v1/golden-hour/google-tasks/lists');
132	      const data = await res.json();
133	      if (data.success && data.lists) {
134	        setTasklists(data.lists);
135	      }
136	    } catch (e) {
137	      console.error('Failed to fetch task lists:', e);
138	    }
139	  };
140	
141	  const fetchESP32Queue = async (listId?: string) => {
142	    try {
143	      const url = listId && listId !== 'all'
144	        ? `http://localhost:8080/api/v1/golden-hour/esp32/queue?limit=3&tasklist_id=${encodeURIComponent(listId)}`
145	        : 'http://localhost:8080/api/v1/golden-hour/esp32/queue?limit=3';
146	      const res = await fetch(url);
147	      const data = await res.json();
148	      if (data.top_task) {
149	        setEsp32Queue({
150	          task_id: data.top_task.task_id,
151	          title: data.top_task.title,
152	          tasklist_title: data.top_task.tasklist_title,
153	          domain: data.top_task.domain,
154	          element: data.top_task.element,
155	          priority: data.top_task.priority,
156	          mode: data.top_task.mode,
157	          target_seconds: data.top_task.target_seconds,
158	          source: 'google_tasks',
159	          queue_count: data.total_in_queue,
160	          last_synced_at: data.last_synced_at
161	        });
162	      } else {
163	        setEsp32Queue(null);
164	      }
165	    } catch (e) {
166	      console.warn('ESP32 queue fetch error:', e);
167	    }
168	  };
169	
170	  const fetchGoogleTasks = async (listId: string = selectedListId) => {
171	    setIsGoogleLoading(true);
172	    setGoogleError(null);
173	    try {
174	      const url = listId === 'all'
175	        ? 'http://localhost:8080/api/v1/golden-hour/google-tasks/tasks?tasklist_id=all'
176	        : `http://localhost:8080/api/v1/golden-hour/google-tasks/tasks?tasklist_id=${encodeURIComponent(listId)}`;
177	
178	      const res = await fetch(url);
179	      const data = await res.json();
180	      if (!res.ok) {
181	        throw new Error(data.detail || `HTTP ${res.status}`);
182	      }
183	      if (data.success) {
184	        setGoogleTasks(data.tasks || []);
185	        if (data.last_synced_at) {
186	          setLastSyncedAt(data.last_synced_at);
187	        }
188	        fetchESP32Queue(listId);
189	      }
190	    } catch (e: any) {
191	      console.error('Failed to fetch Google Tasks:', e);
192	      setGoogleError(e.message || 'Error querying SQLite database');
193	    } finally {
194	      setIsGoogleLoading(false);
195	    }
196	  };
197	
198	  const handleSyncFromGoogle = async () => {
199	    setIsSyncingAPI(true);
200	    setGoogleError(null);
201	    try {
202	      const res = await fetch('http://localhost:8080/api/v1/golden-hour/google-tasks/sync', {
203	        method: 'POST'
204	      });
205	      const data = await res.json();
206	      if (!res.ok) {
207	        throw new Error(data.detail || `HTTP ${res.status}`);
208	      }
209	      setLastSyncedAt(data.last_synced_at);
210	      fetchTasklists();
211	      fetchGoogleTasks(selectedListId);
212	    } catch (e: any) {
213	      console.error('Failed to sync from Google API:', e);
214	      setGoogleError(e.message || 'Error syncing from Google Tasks API');
215	    } finally {
216	      setIsSyncingAPI(false);
217	    }
218	  };
219	
220	  const handleSelectList = (listId: string) => {
221	    setSelectedListId(listId);
222	    fetchGoogleTasks(listId);
223	  };
224	
225	  const handleAuthorizeGoogle = async () => {
226	    setIsAuthorizing(true);
227	    setGoogleError(null);
228	    try {
229	      const res = await fetch('http://localhost:8080/api/v1/golden-hour/google-tasks/auth', {
230	        method: 'POST'
231	      });
232	      const data = await res.json();
233	      if (!res.ok) {
234	        throw new Error(data.detail || `HTTP ${res.status}`);
235	      }
236	      if (data.authenticated) {
237	        setGoogleStatus((prev) => ({ ...prev, credentials_present: true, authenticated: true }));
238	        fetchTasklists();
239	        fetchGoogleTasks('all');
240	      }
241	    } catch (e: any) {
242	      console.error('Authorization error:', e);
243	      setGoogleError(e.message || 'Failed to complete Google OAuth authorization');
244	    } finally {
245	      setIsAuthorizing(false);
246	    }
247	  };
248	
249	  const handleCompleteGoogleTask = async (taskId: string, listId?: string) => {
250	    setCompletingTaskId(taskId);
251	    try {
252	      const res = await fetch('http://localhost:8080/api/v1/golden-hour/google-tasks/complete', {
253	        method: 'POST',
254	        headers: { 'Content-Type': 'application/json' },
255	        body: JSON.stringify({
256	          task_id: taskId,
257	          tasklist_id: listId || selectedListId
258	        })
259	      });
260	      const data = await res.json();
261	      if (data.success) {
262	        // Immediate local filter for instant UX (< 0.2ms)
263	        setGoogleTasks((prev) => prev.filter((t) => t.id !== taskId));
264	        fetchESP32Queue(selectedListId);
265	      }
266	    } catch (e) {
267	      console.error('Error completing task:', e);
268	    } finally {
269	      setCompletingTaskId(null);
270	    }
271	  };
272	
273	  const handleReadNotion = async () => {
274	    setIsNotionLoading(true);
275	    setNotionError(null);
276	    try {
277	      const res = await fetch('http://localhost:8080/api/v1/golden-hour/notion/read', {
278	        method: 'POST',
279	        headers: { 'Content-Type': 'application/json' },
280	        body: JSON.stringify({ database_id: notionDBUrl.trim() })
281	      });
282	      const data = await res.json();
283	      if (!res.ok) {
284	        throw new Error(data.detail || `HTTP ${res.status}`);
285	      }
286	      setNotionTasks(data.tasks || []);
287	      setNotionLastReadAt(data.timestamp || new Date().toISOString());
288	    } catch (err: any) {
289	      setNotionError(err.message);
290	      setNotionTasks([]);
291	    } finally {
292	      setIsNotionLoading(false);
293	    }
294	  };
295	
296	  const filteredTasks = useMemo(() => {
297	    if (!searchQuery.trim()) return googleTasks;
298	    const q = searchQuery.toLowerCase();
299	    return googleTasks.filter(
300	      (t) => t.title.toLowerCase().includes(q) || (t.notes && t.notes.toLowerCase().includes(q))
301	    );
302	  }, [googleTasks, searchQuery]);
303	
304	  // Helper for Element Badge styling
305	  const renderElementBadge = (element?: string) => {
306	    switch (element) {
307	      case 'verdant':
308	        return <span className="px-2 py-0.5 rounded bg-emerald-950/80 border border-emerald-500/30 text-emerald-400 text-[10px] font-mono flex items-center gap-1"><Leaf className="w-2.5 h-2.5" /> Verdant</span>;
309	      case 'void':
310	        return <span className="px-2 py-0.5 rounded bg-purple-950/80 border border-purple-500/30 text-purple-300 text-[10px] font-mono flex items-center gap-1"><Moon className="w-2.5 h-2.5" /> Void</span>;
311	      case 'celestial':
312	        return <span className="px-2 py-0.5 rounded bg-sky-950/80 border border-sky-500/30 text-sky-300 text-[10px] font-mono flex items-center gap-1"><Sparkles className="w-2.5 h-2.5" /> Celestial</span>;
313	      case 'aether':
314	        return <span className="px-2 py-0.5 rounded bg-fuchsia-950/80 border border-fuchsia-500/30 text-fuchsia-300 text-[10px] font-mono flex items-center gap-1"><Cpu className="w-2.5 h-2.5" /> Aether</span>;
315	      case 'solar':
316	      default:
317	        return <span className="px-2 py-0.5 rounded bg-amber-950/80 border border-amber-500/30 text-amber-300 text-[10px] font-mono flex items-center gap-1"><Sun className="w-2.5 h-2.5" /> Solar</span>;
318	    }
319	  };
320	
321	  return (
322	    <div className="space-y-6 max-w-5xl mx-auto w-full p-6 animate-in fade-in duration-300">
323	      {/* Header Banner */}
324	      <div className="p-6 rounded-2xl bg-[#120f18] border border-[#2b2238] flex flex-col md:flex-row items-start md:items-center justify-between gap-4 shadow-xl">
325	        <div className="flex items-center gap-3.5">
326	          <div className="p-3.5 rounded-xl bg-gradient-to-br from-[#291e07] to-[#120f18] border border-[#524124] shadow-inner">
327	            <Zap className="w-7 h-7 text-[#ffd86b]" />
328	          </div>
329	          <div>
330	            <h2 className="font-cinzel text-xl font-bold text-[#ffd86b] flex items-center gap-2">
331	              Task Intake & ESP32 Dispatch Cockpit
332	            </h2>
333	            <p className="text-xs text-[#8c7a9e] mt-0.5">
334	              O(1) SQLite metadata inheritance engine (<span className="text-emerald-400 font-mono font-bold">&lt; 0.5ms</span>) • Tasks inherit parent list rules automatically.
335	            </p>
336	          </div>
337	        </div>
338	
339	        <div className="flex flex-col sm:flex-row items-end sm:items-center gap-3">
340	          {intakeSource === 'google' && (
341	            <span className={`px-3 py-1 rounded-xl text-xs font-mono font-bold border ${
342	              googleStatus?.authenticated
343	                ? 'bg-[#0f281e] text-emerald-400 border-emerald-500/40'
344	                : 'bg-[#2b1e0a] text-[#ffd86b] border-[#d4af37]/40'
345	            }`}>
346	              {googleStatus?.authenticated ? '● SQLITE O(1) ENGINE ACTIVE' : '○ OAUTH READY'}
347	            </span>
348	          )}
349	
350	          {/* Source Selector Tabs */}
351	          <div className="flex items-center p-1.5 rounded-xl bg-[#171320] border border-[#2b2238]">
352	            <button
353	              onClick={() => setIntakeSource('google')}
354	              className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${
355	                intakeSource === 'google'
356	                  ? 'bg-gradient-to-r from-[#ffd86b] to-[#c29a3e] text-[#120f18] shadow-md shadow-[#ffd86b]/10'
357	                  : 'text-[#8c7a9e] hover:text-white'
358	              }`}
359	            >
360	              <Zap className="w-3.5 h-3.5" />
361	              Google Tasks ({googleTasks.length})
362	            </button>
363	            <button
364	              onClick={() => setIntakeSource('notion')}
365	              className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${
366	                intakeSource === 'notion'
367	                  ? 'bg-gradient-to-r from-[#ffd86b] to-[#c29a3e] text-[#120f18] shadow-md shadow-[#ffd86b]/10'
368	                  : 'text-[#8c7a9e] hover:text-white'
369	              }`}
370	            >
371	              <Database className="w-3.5 h-3.5" />
372	              Notion
373	            </button>
374	          </div>
375	        </div>
376	      </div>
377	
378	      {/* ESP32 Live Telemetry Monitor */}
379	      <div className="p-5 rounded-2xl bg-gradient-to-r from-[#171320] to-[#1a1226] border border-[#d4af37]/30 shadow-xl flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
380	        <div className="flex items-center gap-3">
381	          <div className="p-2.5 rounded-xl bg-[#2b1e0a] border border-[#d4af37]/40 text-[#ffd86b]">
382	            <Radio className="w-5 h-5 animate-pulse" />
383	          </div>
384	          <div>
385	            <div className="flex items-center gap-2">
386	              <span className="text-xs font-mono font-bold text-[#ffd86b]">ESP32 ACTIVE TRIPLET QUEUE</span>
387	              <span className="px-2 py-0.5 rounded-full bg-emerald-950/80 text-emerald-400 border border-emerald-500/30 text-[10px] font-mono">
388	                BROADCASTING
389	              </span>
390	            </div>
391	            <p className="text-sm font-semibold text-white mt-0.5">
392	              {esp32Queue?.title || 'No Active Directive'}
393	            </p>
394	          </div>
395	        </div>
396	        <div className="text-right font-mono text-xs text-[#8c7a9e] shrink-0">
397	          <div>Category: <strong className="text-[#ffd86b]">{esp32Queue?.tasklist_title || 'All Lists'}</strong></div>
398	          <div>Total in Queue: <strong className="text-white">{esp32Queue?.queue_count || 0} Directives</strong></div>
399	        </div>
400	      </div>
401	
402	      {/* VIEW 1: GOOGLE TASKS (RAPID MULTI-LIST INTAKE) */}
403	      {intakeSource === 'google' && (
404	        <div className="space-y-6">
405	          {/* OAuth Activation Banner if not authenticated */}
406	          {!googleStatus?.authenticated && (
407	            <section className="p-6 rounded-2xl bg-[#171320] border border-[#ffd86b]/40 shadow-xl space-y-4">
408	              <div className="flex items-start justify-between gap-4">
409	                <div className="space-y-1">
410	                  <h3 className="font-cinzel text-base font-bold text-[#ffd86b] flex items-center gap-2">
411	                    <Key className="w-5 h-5" />
412	                    One-Click Google Account Connection
413	                  </h3>
414	                  <p className="text-xs text-[#8c7a9e] leading-relaxed">
415	                    Credentials ready in <code className="text-white">backend/auth/credentials.json</code>. Click to authorize Google Tasks access.
416	                  </p>
417	                </div>
418	                <button
419	                  onClick={handleAuthorizeGoogle}
420	                  disabled={isAuthorizing}
421	                  className="px-6 py-3 rounded-xl bg-gradient-to-r from-[#ffd86b] to-[#c29a3e] text-[#120f18] text-xs font-bold font-mono hover:brightness-110 active:scale-[0.98] transition-all flex items-center gap-2 shadow-lg shadow-[#ffd86b]/10 shrink-0 disabled:opacity-50"
422	                >
423	                  <LogIn className={`w-4 h-4 ${isAuthorizing ? 'animate-spin' : ''}`} />
424	                  {isAuthorizing ? 'Connecting...' : 'Connect Google Tasks'}
425	                </button>
426	              </div>
427	            </section>
428	          )}
429	
430	          {/* Error Banner */}
431	          {googleError && (
432	            <section className="p-6 rounded-2xl bg-[#2b1018] border border-rose-500/50 shadow-2xl animate-in fade-in duration-200">
433	              <div className="flex items-start gap-3.5">
434	                <ShieldAlert className="w-6 h-6 text-rose-400 shrink-0 mt-0.5" />
435	                <div className="space-y-2">
436	                  <h4 className="font-cinzel text-sm font-bold text-rose-300 uppercase tracking-wide">
437	                    [FAIL LOUDLY] Google Tasks Error
438	                  </h4>
439	                  <p className="text-xs text-rose-200 font-mono whitespace-pre-wrap bg-[#17080c] p-3.5 rounded-xl border border-rose-500/30">
440	                    {googleError}
441	                  </p>
442	                </div>
443	              </div>
444	            </section>
445	          )}
446	
447	          {/* MULTI-LIST CATEGORY FILTER BAR WITH INHERITED CONDITIONS */}
448	          {tasklists.length > 0 && (
449	            <section className="p-4 rounded-2xl bg-[#171320] border border-[#2b2238] space-y-3 shadow-lg">
450	              <div className="flex items-center justify-between">
451	                <div className="flex items-center gap-2 text-xs font-semibold text-[#ffd86b] uppercase tracking-wide">
452	                  <Layers className="w-4 h-4" />
453	                  List Categories & Metadata Partitions ({tasklists.length})
454	                </div>
455	                <div className="flex items-center gap-2">
456	                  {lastSyncedAt && (
457	                    <span className="text-[11px] font-mono text-[#8c7a9e] hidden sm:inline flex items-center gap-1">
458	                      <Clock className="w-3 h-3 text-[#ffd86b]" />
459	                      Synced: {new Date(lastSyncedAt).toLocaleTimeString()}
460	                    </span>
461	                  )}
462	                  <button
463	                    onClick={handleSyncFromGoogle}
464	                    disabled={isSyncingAPI}
465	                    title="Pull fresh updates from Google API into SQLite database"
466	                    className="px-3 py-1.5 rounded-lg bg-[#2b1e0a] border border-[#d4af37]/40 text-xs font-mono font-bold text-[#ffd86b] hover:brightness-110 flex items-center gap-1.5 transition-all shadow-md shadow-[#ffd86b]/5 disabled:opacity-50"
467	                  >
468	                    <CloudDownload className={`w-3.5 h-3.5 ${isSyncingAPI ? 'animate-spin' : ''}`} />
469	                    {isSyncingAPI ? 'Syncing...' : 'Sync from Google'}
470	                  </button>
471	                </div>
472	              </div>
473	
474	              {/* Scrollable List Chips */}
475	              <div className="flex items-center gap-2 overflow-x-auto pb-1.5 scrollbar-thin scrollbar-thumb-[#2b2238]">
476	                <button
477	                  onClick={() => handleSelectList('all')}
478	                  className={`px-3.5 py-1.5 rounded-xl text-xs font-mono font-bold whitespace-nowrap transition-all border shrink-0 ${
479	                    selectedListId === 'all'
480	                      ? 'bg-[#2b1e0a] text-[#ffd86b] border-[#d4af37]'
481	                      : 'bg-[#120f18] text-[#8c7a9e] border-[#2b2238] hover:text-white'
482	                  }`}
483	                >
484	                  ★ All Lists Combined
485	                </button>
486	                {tasklists.map((tl) => (
487	                  <button
488	                    key={tl.id}
489	                    onClick={() => handleSelectList(tl.id)}
490	                    className={`px-3.5 py-1.5 rounded-xl text-xs font-mono whitespace-nowrap transition-all border shrink-0 flex items-center gap-1.5 ${
491	                      selectedListId === tl.id
492	                        ? 'bg-[#2b1e0a] text-[#ffd86b] border-[#d4af37] font-bold'
493	                        : 'bg-[#120f18] text-[#8c7a9e] border-[#2b2238] hover:text-white'
494	                    }`}
495	                  >
496	                    <span>{tl.title}</span>
497	                    {tl.conditions?.domain && (
498	                      <span className="text-[10px] text-[#8c7a9e] font-normal">
499	                        ({tl.conditions.domain})
500	                      </span>
501	                    )}
502	                  </button>
503	                ))}
504	              </div>
505	            </section>
506	          )}
507	
508	          {/* Active Tasks Feed with Inherited Metadata */}
509	          <section className="p-6 rounded-2xl bg-[#171320] border border-[#2b2238] space-y-4 shadow-lg">
510	            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-[#2b2238] pb-3">
511	              <div className="flex items-center gap-2">
